do $do$ begin
if not exists(select 1 from project_cost_items where cost_item_id='ci2_c_led_power' and quantity is not distinct from 108.9 and confidence is not distinct from 'H' and source_kind is not distinct from '推定' and note is not distinct from '推定値。**2026-09-22 に新しく入れた**（まさ 2026-09-22「光はLEDで当ててるよ。どのくらいの光量を当てたらいいのかは先生も知らない。なので推定して入れてほしい」）。LED の電気代は、光の強さの選び方より、**菌体1kgを作るのに光合成に使える光の粒（光子）が何モル要るか**で決まる。出し方: 1,000 g ÷ 光に対する菌体の収率 1.0 g/mol ÷ 培養液に吸われる割合 0.85 ÷ LED の光合成光量子効率 3.0 μmol/J ＝ 392,156,863 J ＝ 108.9 kWh/kg-DCW。**収率 1.0 g/mol**: シアノバクテリア Synechocystis の実測 1.0〜1.72 g/mol（赤色の光・中程度の強さ。PLOS ONE の藍藻と緑藻の比較研究）、連続培養のエネルギー収支で 1.24 g/mol（Touloupakis ら）、緑藻 Chlorella・Dunaliella の平板型の培養槽で 0.6〜0.8 g/mol（Zijffers ら 2010）。窒素源が硝酸のときの理論上の上限は 1.5 g/mol（同じ Zijffers ら 2010。光子8個で CO2 1分子という単純な値 約3 g/mol は、窒素を還元する分の光を数えていない）。SX の株（好熱性）の実測は無いので、上限の3分の2で置いた。**吸われる割合 0.85**: 文献値は見つからず、培養槽の設計で光を吸い切る前提の見当（0.7〜0.95）。**光合成光量子効率 3.0 μmol/J**: 園芸用 LED の業界基準（DLC 園芸照明 V4.0、2025年）の下限が 2.5、いまの上位の製品が 3.0〜3.3。**確かめ方**: 人工光で藻を育てる技術経済評価（Blanken ら 2013、Algal Research「Cultivation of microalgae on artificial light comes at a cost」）は、電気が菌体の化学エネルギーになる割合を4〜6%としていて、逆算すると菌体1kgあたり 92〜168 kWh。この行はその範囲に入る。同じ論文は、人工光は高く売れる製品でなければ割に合わないとしている。**幅**: 収率 0.6〜1.5 g/mol・効率 2.5〜3.5 μmol/J で、菌体1kgあたり 60〜230 kWh くらい動く。**加温との関係**: LED に入れた電気はほぼすべて熱になる（菌体1kgあたり約392 MJ）。加温の熱の見積（200 MJ/kg-DCW、屋外で日射を受ける前提）を上回るので、LED の熱を培養液に回せる室内の設計なら、加温の熱の行はほぼ0円になり、逆に冷やす費用が要ることもある。いまは両方を数えている（その分だけ多めに出ている）。**光の強さの目安**: 1系列（1日111kg）が要る光は毎秒約1.5 mol（排液で増える速さの倍率が1のとき）。光の強さを 300 μmol/m²/s にすると、照らす面は約5,000 m²。シアノバクテリアの培養では、実験室で 50〜200、好熱性の株の実証に近い平板型で 500〜2,000 μmol/m²/s が使われている。培養の電力（撹拌・送液・散気）の行とは別。買値は高圧受電の 17.45 円/kWh（燃料化設備の電力と同じ）。') then raise exception '487: input drift ci2_c_led_power'; end if;
if not exists(select 1 from project_cost_items where cost_item_id='ci2_c_led_capex' and quantity is not distinct from 15.1 and unit_price is not distinct from 315 and useful_life_years is not distinct from 7 and note is not distinct from '推定値。**2026-09-22 に新しく入れた**（まさ 2026-09-22「光はLEDで当ててるよ。どのくらいの光量を当てたらいいのかは先生も知らない。なので推定して入れてほしい」）。作る菌体が増えるとその分だけ器具が要るので、系列ではなく**菌体1kgあたりの量**で持つ（系列の大きさや、排液で増える速さの倍率では薄まらない。速く増やすにはその分の光が要る）。数量は、年に1kg作るのに置く LED の電力 ＝ 108.9 kWh ÷ 1年に点ける時間 7,200時間（300日 × 24時間、ずっと点ける前提）＝ 15.1 W。単価は、業務用の園芸用 LED の価格 1 μmol/s あたり 0.4〜1.0 ドル（Fluence の SPYDR など、2025年）の真ん中 0.7 ドル、1ドル150円、3.0 μmol/J で 315円/W。耐用年数は、寿命 50,000時間（L90。業務用で 50,000〜90,000時間）÷ 7,200時間 ＝ 約7年。初期投資は 15.1 W × 315円 ＝ 菌体を年に1kg作るごとに約4,756円。1日のうち点ける時間を短くすると、同じ光を短い時間で当てるので器具は増える（16時間なら1.5倍、電気代は同じ）。大量に買ったときの値引きは入れていない。確かめ方: 同じ規模の植物工場・藻の培養施設の照明の見積（器具1台の値段と、1台が出す光 μmol/s）を取り、1 μmol/s あたりの値段で比べる。') then raise exception '487: input drift ci2_c_led_capex'; end if;
if not exists(select 1 from project_cost_assumptions where cost_assumption_id='ca_recovery_eta' and value is not distinct from 90.0 and confidence is not distinct from 'H' and source_kind is not distinct from '仮置き' and owner is not distinct from '中島先生' and note is not distinct from 'V-501。00_変数辞書 Mid/プロセス分解P2。2026-09-15 から、処理のあと回収して次のバッチへ回せる菌体の割合として使う（中島先生 2026-08-28 のレビュー「回収率と初回必要投入量が混同されている」「回収率は「次バッチへ再利用できる量」に使用」、ちこさん 2026-09-15 の指摘）。毎バッチ、前のバッチから回した菌体に新しい菌体を足して、1バッチに要る菌体（（流入の濃さ − 目標放流水濃度）÷ 取り込み効率）にそろえる。回した菌体は1回ごとに η 倍になり、使用回数を使い切ったら入れ替えるので、新しく入れる菌体 ＝ 1バッチに要る菌体 ×（1 − η）÷（1 − η^使用回数）。色素分解（使用回数10回）では、90%で要る量の15.4%、95%で12.5%、98%で10.9%、100%で10.0%（使用回数で割るだけ）。使用回数1回の金属回収には効かない（毎バッチ要る量をそのまま新しく入れる）。回収できずに失う菌体と、使用回数を使い切って入れ替える菌体は、この新しく入れる量に入るので、明細の「菌体ロス補充分」「菌体性能低下による交換・再生分」は0円にした。確かめ方: 装置（循環カートリッジ・直接投入）ごとに、処理のあと次のバッチへ回せる菌体の割合を中島先生に聞く（確認事項）。2026-07 の設備アドオン試算は、色素分解の運転ロスを2%（回収率98%にあたる）で置いていた。前の使い方（2026-09-15 まで）: 必要な菌体を η で割っていた（260820版の③シートと同じ式。金属50ppm ÷ 取り込み効率0.05 ÷ 0.9 ＝ 1,111 g/m³）。') then raise exception '487: input drift ca_recovery_eta'; end if;
if not exists(select 1 from project_cost_tasks where cost_task_id='ct_run_injection' and hours_per_occurrence is not distinct from 7.5 and confidence is not distinct from 'A' and source_kind is not distinct from '先生回答' and owner is not distinct from '中島先生' and note is not distinct from '出所：中島試算シート100m³ケース②投入。手動運用のときの時間。自動制御の無人運転で何時間まで減るかは未確認（ダイキアクシスへ確認中）。 オフサイトでも、同じ運転をSX工場で行う前提で同じ時間を使う。 作業を誰がやるかは「処理する場所の人」: オンサイトでは顧客がやる作業として、SXの原価にも作業時間にも入れない（2026-09-14 まさ「全顧客の工場にSXの社員が張り付くってありえない」）。オフサイトではSX工場でSXがやるので、SXの原価に入れる。') then raise exception '487: input drift ct_run_injection'; end if;
if not exists(select 1 from project_cost_tasks where cost_task_id='ct4_culture_operation' and hours_per_occurrence is not distinct from null and confidence is not distinct from 'H' and source_kind is not distinct from '仮置き' and owner is not distinct from '杉浦先生・中島先生' and note is not distinct from '毎日の培養の管理と、菌体を濃縮して出荷できる状態にする作業。1日あたりの工数が分かっていないので空欄（未確認）にしている。年間回数は稼働日と同じ300日で置いた。工数が分かれば、菌体1kgの原価に入る。 2026-09-14 から、培養設備の系列ごとの作業として数える（1系列あたり年300日 × 系列数）。') then raise exception '487: input drift ct4_culture_operation'; end if;
if not exists(select 1 from project_cost_tasks where cost_task_id='ct4_post_dye' and hours_per_occurrence is not distinct from null and confidence is not distinct from 'H' and source_kind is not distinct from '仮置き' and owner is not distinct from 'ダイキアクシス' and note is not distinct from '使用済み菌体を脱水し、汚泥として処分業者へ引き渡すまでの作業。工数は未確認で空欄。処分費は明細の「使用済み菌体の処分」に積んでいる。 2026-09-14 から、オンサイトでは顧客工場で出る汚泥として顧客がやる。SX工場で処理するオフサイトではSXがやる。') then raise exception '487: input drift ct4_post_dye'; end if;
if not exists(select 1 from project_cost_assumptions where cost_assumption_id='ca_sale_price' and label is not distinct from '想定売上単価（オンサイト）' and note is not distinct from '既存処理コスト500円/m³前後という前提から置いた値。用途別の実勢価格では未検証。 オンサイト（顧客工場で処理）の売価。オフサイトは「想定売上単価（オフサイト）」を別に置く（2026-09-14 まさ）。') then raise exception '487: input drift ca_sale_price'; end if;
if not exists(select 1 from project_cost_assumptions where cost_assumption_id='ca11_offsite_annual_volume' and label is not distinct from '年間処理量（オフサイト）' and note is not distinct from 'オフサイト（顧客の排液をSX工場まで運んで処理）は、将来サイドビジネスとして足す形で、オンサイトと別に年間処理量を置く（2026-09-14 まさ「オフサイトは売価も処理量も別に分けて試算したい」「将来的にサイドビジネス的に、オフサイトもやれたらいいかなっていうくらいのadditionalな要素」）。30,000m³/年は、SX工場1か所がいまの前提（100m³/日 × 300日）で処理する量として置いた仮置き。オフサイトの売上・事業全体の年間・顧客数はこの量で出す。菌体の製造拠点で年に作る量は、この量にオフサイトの濃さで使い切る菌体量を掛けて、オンサイトの分に足して計算する（同じ製造拠点で作る）。') then raise exception '487: input drift ca11_offsite_annual_volume'; end if;
if not exists(select 1 from project_cost_assumptions where cost_assumption_id='ca_batch_volume' and label is not distinct from 'バッチ容量' and note is not distinct from '出どころ: ちこさんの試算シート 2026-08-20版の共通前提「バッチ容量 100 m³/バッチ」（メモなし）。同じ表の日処理量 100m³/日のメモは「260812打合せ：m³/日基準」（中島先生との打合せ）。1日1バッチとして、年間バッチ数 ＝ 稼働日/年 × 稼働率。確かめ方: 顧客工場の調整槽の容量と、1日に処理する量を聞いて比べる。') then raise exception '487: input drift ca_batch_volume'; end if;
if not exists(select 1 from project_cost_models where cost_model_id='cm_p21_260820' and version_label is not distinct from '260914版' and summary_md is not distinct from 'SXの排液処理を、**菌体の製造原価**と**用途別の処理原価**の二段階で試算する。

**事業の規模は売上10,000,000,000円** — IPOできる大量生産の状態を前提に、年間処理量を20,000,000m³/年で置く（売価500円/m³で売上10,000,000,000円。2026-09-14 まさ）。顧客1社あたり年30,000m³なら約667社分。**オフサイトは、将来サイドビジネスとして足す形で、売価と年間処理量をオンサイトと別に置く**（仮置き 50,000円/m³＝1Lあたり50円・30,000m³/年。2026-09-14 まさ「ペインがあれば割高でも成立するから」）。引き取る液は顧客工場の排水より濃いので、対象物質の濃度もオフサイトだけ別に置く（仮置き 色素1,000mg/L・金属5,000ppm。2026-09-14 まさ「置いて」）。菌体の製造拠点で年に作る量は、色素分解が株によらず約2,855t、金属回収が自然株で約22,612t・強化株で約17,919t（強化株は金属の取り込み効率が高い）。

**第1段 菌体の製造原価** — 株（強化株／自然株）ごとに、菌体の製造拠点で乾燥菌体1kgをつくる原価を出す。菌体の製造拠点は、顧客工場では培養せず、SX側でまとめて菌体を育て、濃縮して各工場へ運ぶところ。**年に作る量は計算で出す**（（オンサイトの年間処理量 × オンサイトで使い切る菌体量 ＋ オフサイトの年間処理量 × オフサイトで使い切る菌体量）÷ 販売率）。今の明細を培養設備の1系列として必要な数だけ並べるので、設備・固定費・系列ごとの作業は1kgあたり変わらず、拠点に1つの作業だけが量で薄まる。同じ株なら、1kgあたりの原価は用途でほとんど変わらない（自然株で3,521.0円、強化株で色素分解 3,542.5円・金属回収 3,542.4円。工場の排熱・排ガス・排液を使わないとき。2026-09-15 に培養の加温・電力・排水を、2026-09-22 に培養の LED の照明を足した）。いちばん大きいのは LED の照明（電気代 1,900円・器具 680円。光の量は推定）で、次が加温の熱（460円）。菌体の量に比例する培養の原料（窒素源・リン源・CO2・水など）は、菌体の成分と公開の買値から「使う量 × 買値」で置いている（2026-09-14、菌体1kgあたり274.6円のうちCO2 114.5円・窒素源 90.8円）。強化株は閉鎖系の追加費用が乗る。生産した菌体のうち売れる割合（販売率）で割るので、売れ残りが出ると1kgあたりの原価は上がる。

**第2段 用途別の処理原価** — 第1段の原価を一定として、色素分解と金属回収のそれぞれで排水1m³あたりの総コストを出す。用途で変わるのは、必要な菌体の量（1バッチに要る菌体 ＝（流入の濃さ − 目標放流水濃度）÷ 取り込み効率 を、回収率と菌体使用回数から毎バッチ新しく入れる量にしたもの。2026-09-15 から）と、使用済み菌体の後処理（金属回収は中央回収設備の償却を含む）。対象物質の濃度はオフサイトだけ別に置くので、同じ用途でもオフサイトは使い切る菌体の量が多い（金属回収で約125倍、色素分解で約22倍）。菌体を使い回せるのは色素分解だけで、金属回収は酸で菌体を溶かして金属を取り出すので、使用回数は1回で固定する。色素分解は10回使い回す前提で置いている（2026-07の設備アドオン試算と同じ。杉浦先生に確認中）。

**方式と装置を分けて並べる** — 方式は、顧客工場で処理するオンサイトと、排液をSX工場まで運んで処理するオフサイトの2つ。装置は、菌体を筒に閉じ込めて排液を通す循環カートリッジと、菌体を槽に入れて混ぜ膜でこし取る直接投入の2つで、どちらの方式でも選べる。

**SXの原価に入れるのはSXがやる作業だけ** — 顧客工場での処理の運転は顧客がやる作業として、SXの原価にも作業時間にも入れない。オフサイトではSX工場でSXが運転するので、SXの原価に入る。

**顧客工場の設備・装置の費用と汚泥の処分は顧客が持つ** — 顧客工場に置くリアクター（処理設備）と槽は顧客が買い、装置を動かす消耗品・電力・点検・交換部品（循環カートリッジの菌体保持モジュールを含む）、処理水の分析と薬剤、顧客工場で出る使用済み菌体の汚泥の処分も顧客が持つ（2026-09-14 まさ）。いずれもSXの原価に入れない。オンサイトでSXの原価に残る現場の費用は、菌体を運ぶ巡回と容器（回収できずに失う菌体の補充は、2026-09-15 から菌体費に入る）、モジュールや膜の交換の作業、立入制限と教育訓練（強化株）。明細ごとに誰が持つか（SX / 顧客 / 処理する場所の持ち主）を持ち、画面で変えられる。SX工場で処理するオフサイトでは、設備・槽・装置の費用・汚泥の処分はSXが持つ。

操作パネルで株・用途・方式・装置を切り替え（開いたときは自然株）、前提・作業リスト・明細の数字を書き換えると、結果がその場で再計算される。前提・作業リスト・明細は「事業と処理の条件」「CAPEX（初期投資）」「OPEX（毎年の費用）」の3つに分け、その中を小分けにして並べる。作業単価はすべての作業に共通の1つ。選んだ組み合わせで使わない前提・作業・明細は薄く出る。結果の欄には総コストの内訳を棒グラフで出し、操作パネルの一番上には作業の流れと段ごとの年間工数を出す。書き換えた数字は保存されない。正本へ書くのは、管理者が「この値を保存」を押したときだけ。

ちこ作成の260820版の明細を土台に、2026-09-13に二段階へ組み替えた。人件費・巡回サービス・閉鎖系の追加費用・色素用の後処理・色素の濃さを追加し、いずれも確度つきで置いている。同日、人件費を作業リスト（作業ごとの工数 × 作業単価）で持つ形に変え、販売率を足した。さらに同日、作業を流れの段に並べ直し、オフサイトの比較を足した。2026-09-14 に、方式（オンサイト / オフサイト）と装置（循環カートリッジ / 直接投入）を分け、作業ごとに誰がやるかを持たせた。同日、色素分解の菌体使用回数を10回にし、顧客工場のリアクター・槽と汚泥の処分を顧客が持つ形にした。同日、年間生産能力を入力から外し、年間処理量（売上10,000,000,000円に届く20,000,000m³/年）から年に作る量を計算する形にした。同日、作業単価をすべての作業に共通の1つにし、前提・作業リスト・明細を「事業と処理の条件 / CAPEX / OPEX」の区分に並べ直した。同日、上端の槽の表示を外し、選んだ組み合わせで使わない前提を薄く出すようにした。同日、顧客工場の装置の消耗品・電力・点検・交換部品を顧客の持ち分にし、オフサイトの循環カートリッジの処理の運転をSXの作業にした。同日、金額をカンマ区切りの円にそろえた（10,000,000,000円の形。億・万で丸めない）。同日、オフサイトの売価と年間処理量をオンサイトと別の前提に分けた。' and system_scope_md is not distinct from '**対象** — 工場排液を、生きたシアノバクテリア（藍藻）で処理する。用途は色素分解と金属回収の2つを並べる。

**規模** — オンサイトで年間 20,000,000 m³（売価500円/m³で売上10,000,000,000円。IPOできる大量生産の状態、2026-09-14 まさ）。オフサイトは将来のサイドビジネスとして、年間 30,000 m³・売価50,000円/m³（1Lあたり50円）で別に置く（仮置き、2026-09-14 まさ）。引き取る液の濃さも別に置く（仮置き 色素1,000mg/L・金属5,000ppm。オンサイトは色素50mg/L・金属50ppm。2026-09-14 まさ）。顧客工場1拠点あたり 100 m³/日 × 300 日/年 ＝ 30,000 m³/年で、約667社分。1バッチ100 m³、反応時間（HRT）4時間のバッチ運転。

**第1段：菌体は菌体の製造拠点で作る** — 顧客工場では培養せず、SX側でまとめて菌体を育て、濃縮して各工場へ運ぶ。年に作る量 ＝（年間処理量（オンサイト）× オンサイトで使い切る菌体量 ＋ 年間処理量（オフサイト）× オフサイトで使い切る菌体量）÷ 販売率（入力ではなく計算。2026-09-14 まさ）。今の明細を培養設備の1系列（年33,333kg、仮置き）として、年に作る量 ÷ 1系列 の数だけ並べ、1拠点に置く。乾燥菌体1kgあたりの原価は、「(設備の償却年額 ＋ 年ごとの固定費 ＋ 製造拠点の作業) ÷ 年に作る量 ＋ 菌体量に比例する費用」を販売率で割って出す。設備・固定費・系列ごとの作業（培養の運転・密閉性能検査・除菌フィルター交換）は系列の数だけ増え、拠点に1つの作業（安全委員会の運営など）は増えない。量産で設備や原料をまとめて買ったときの値下がりは入れていない。

**第2段：方式と装置を分けて比較する**

方式（どこで処理するか）
- **オンサイト** — 顧客工場の槽の横に、顧客が買ったリアクター（装置）を置いて処理する。処理の運転と、使用済み菌体の汚泥の処分は顧客がやる。装置を動かす消耗品・電力・点検・交換部品と、処理水の分析・薬剤も顧客が持つ（2026-09-14 まさ）。SXは菌体の搬入・搬出や交換で巡回する。槽は、既存調整タンクの流用でも新設でも顧客の設備
- **オフサイト** — 排液をタンクローリーでSX工場まで運び、SX工場に新設する槽で処理する。処理の運転はSXがやり、処理水はSX工場から流す。顧客工場への巡回と、顧客工場内の区画・立入制限は発生しない。代わりに、排液の輸送・受け入れ・放流の費用が乗る。設備・槽・装置の費用・汚泥の処分はSXが持つ。処理の運転は、循環カートリッジも直接投入もSXがやる

装置（菌体と排液をどう触れさせるか。どちらの方式でも選べる）
- **循環カートリッジ** — 菌体をカートリッジ内の保持モジュールに留め、排液を循環させて接触させる。モジュールは耐用バッチ数ごとに交換する
- **直接投入** — 菌体を槽へ直接投入して撹拌し、反応後に UF/MF 膜で菌体を分離回収する。膜は約3年で交換する

**槽** — オンサイトの槽は顧客の設備（既存調整タンクの流用でも新設でも）で、SXの原価に入らない（2026-09-14 まさ）。オフサイトは SX工場にコンクリート地下タンク100 m³（18,000,000円・10年償却）を新設する。用途ごとに、オンサイト2通り（装置2）とオフサイト2通り（装置2）の4シナリオになる。オンサイトの槽をSXが持つ形に変えると、既設（0円）／新設の2通りに戻る。

**使用済み菌体の後処理** — 金属回収は、SXが使用済み菌体を引き取って酸で溶かし、金属を回収する（SXの原価）。酸で溶かし中和・固液分離をする中央回収設備の初期投資も、使用済み菌体1kgあたりの償却として入れている（2026-09-15 から。見積は無い）。色素分解は使用済み菌体を脱水汚泥として処分し、オンサイトでは顧客がやる（SXの原価に入れない）。

**菌体の量** — 1バッチに要る菌体 ＝（流入の濃さ − 目標放流水濃度）÷ 取り込み効率。回収率は、処理のあと回収して次のバッチへ回せる菌体の割合として使い、使用回数（色素分解10回・金属回収1回）と組み合わせて、毎バッチ新しく入れる菌体を出す（菌体のバッチ間のマスバランス。中島先生 2026-08-28 のレビュー、2026-09-15 から）。回収できずに失う分と、使用回数を使い切って入れ替える分はこの量に入る。菌体の製造拠点で培養に失敗して作り直す分（培養ロス補充）は、別に菌体1kgの原価に入れている。金属の取り込み効率は24時間の単回試験の値で、反応時間4時間とはそろっていない。

**オンサイトの設備は独立プラント新設ではなく増分アドオン** — 顧客の既存調整タンク・排水ライン・ユーティリティ・主処理設備を使い、密閉接触・循環、菌体捕捉、回収サービスを足す（2026-07-23 確定）。このリアクターは顧客が買う（2026-09-14 まさ）。

**収益モデル** — 処理費のみ。売価はオンサイト500円/m³、オフサイト50,000円/m³（自社で処理しにくい液を引き取る値段）。回収物（金属など）の売却収入はまだモデルに入れていない。

