do $constraint$ begin if not exists(select 1 from pg_constraint where conname='project_cost_items_price_rule_check' and conrelid='project_cost_items'::regclass and pg_get_constraintdef(oid)='CHECK (((price_rule IS NULL) OR (price_rule = ANY (ARRAY[''biomass''::text, ''broth''::text, ''module_swap''::text, ''power_circulation''::text, ''power_injection''::text, ''spent_disposal''::text, ''co2_supply''::text, ''culture_loss''::text, ''medium_supply''::text, ''heat_supply''::text, ''recovery_capex''::text]))))') then raise exception '487: price rule constraint drift'; end if; end $constraint$;
alter table project_cost_items drop constraint project_cost_items_price_rule_check;
alter table project_cost_items add constraint project_cost_items_price_rule_check check(price_rule is null or price_rule in ('biomass','broth','module_swap','power_circulation','power_injection','spent_disposal','co2_supply','culture_loss','medium_supply','heat_supply','recovery_capex','culture_cooling','flue_gas_transport','business_overhead'));
update project_cost_items set quantity=52.68426321057899,confidence='H',source_kind='推定',note='好条件の工学仮定。菌体収率1.5g/吸収光子mol、吸収率95%、器具効率3.7µmol/J。1000÷1.5÷0.95÷3.7÷3.6＝52.684kWh/kg。SOL株の実測ではない。入射光あたり1.425g/molは参考のシアノバクテリア約1.5g/molを超えない。短光路と混合を要する。数量を変える場合は器具容量も照合。根拠: https://link.springer.com/article/10.1007/s10126-010-9258-2 、https://www.usa.lighting.philips.com/application-areas/specialist-applications/horticulture/greenpower-specialist-applications/led-toplighting 。加温購入費は排熱ONで0、冷却電力は別計上。' where cost_item_id='ci2_c_led_power';
update project_cost_items set quantity=7.317258779247082,unit_price=388.5,useful_life_years=5,note='好条件の設計仮定。52.684kWh/kg÷7200h×1000＝7.317W/(年産kg)。光子量の買値105円/(µmol/s)を維持し、3.7µmol/Jで388.5円/W。価格を値下げしていない。器具36,000h÷年7200h＝5年。園芸器具の仕様を参考とし、培養への適合・配線・防水・冷却機器の見積は未確認。光路2cm・800µmol/m²/s・菌体5g/Lなら1系列133,332kg/年に照射面約4512m²、液量約90m³、LED約976kWが要る。既存873万円/系列の本体設備がこの規模を満たす見積ではない。' where cost_item_id='ci2_c_led_capex';
update project_cost_assumptions set value=98,confidence='H',source_kind='推定',owner='AMD（内部）',note='好条件の設計仮定。2026-07設備アドオン試算の運転ロス2%を採用。処理後に次バッチへ回せる菌体98%であり、金属回収には効かない。色素分解10回の活性維持と回収率を同時に実証する。必要補充量＝B×(1−η)/(1−η^N)。50→5mg/L、α0.05g/g、10回なら0.098400kg/m³。αは金属から借りた未測定仮定。実測値として扱わない。' where cost_assumption_id='ca_recovery_eta';
update project_cost_tasks set hours_per_occurrence=0.5,confidence='H',source_kind='推定',owner='AMD（内部）',note='自動化の好条件設計枠0.5人時/100m³。始動・終了確認、記録、軽微な操作。制御440万円を含む現場設備2565万円を残す。8/12議論は自動運転を想定するが、0.5hの実測ではない。膜清掃・準備・回収等の他作業は既存行へ残し、槽内清掃は別作業。旧7.5hは手動運転の回答で、変更記録に保持。' where cost_task_id='ct_run_injection';
update project_cost_tasks set hours_per_occurrence=4,confidence='H',source_kind='推定',owner='AMD（内部）',note='好条件の設計仮定。培養・濃縮・出荷状態までを1系列日4人時で計上。年300日×必要系列数。空欄を0円とせず工数を置いた。実測と作業分解で再確認。' where cost_task_id='ct4_culture_operation';
update project_cost_tasks set hours_per_occurrence=0.1,confidence='H',source_kind='推定',owner='AMD（内部）',note='好条件の設計仮定。脱水・処分手配を1バッチ0.1人時。処分料金は既存の別明細。顧客の実人件費・清掃工数と重複を確認。' where cost_task_id='ct4_post_dye';
update project_cost_assumptions set label='SOL単独の仮料金（総額上限未設定時）',note='既存処理コスト500円/m³前後という前提から置いた値。用途別の実勢価格では未検証。 オンサイト（顧客工場で処理）の売価。オフサイトは「想定売上単価（オフサイト）」を別に置く（2026-09-14 まさ）。 顧客総額の上限があるオンサイトは、この値で請求せず、総額上限から顧客負担を引いた料金上限を計算する。' where cost_assumption_id='ca_sale_price';
update project_cost_assumptions set label='引き取る排水の事業全体年間量（オフサイト）',note='オフサイト（顧客の排液をSX工場まで運んで処理）は、将来サイドビジネスとして足す形で、オンサイトと別に年間処理量を置く（2026-09-14 まさ「オフサイトは売価も処理量も別に分けて試算したい」「将来的にサイドビジネス的に、オフサイトもやれたらいいかなっていうくらいのadditionalな要素」）。30,000m³/年は、SX工場1か所がいまの前提（100m³/日 × 300日）で処理する量として置いた仮置き。オフサイトの売上・事業全体の年間・顧客数はこの量で出す。菌体の製造拠点で年に作る量は、この量にオフサイトの濃さで使い切る菌体量を掛けて、オンサイトの分に足して計算する（同じ製造拠点で作る）。 顧客1工場の年30,000m³とは別の入力。どちらも排水量で、培養拠点の菌体能力ではない。' where cost_assumption_id='ca11_offsite_annual_volume';
update project_cost_assumptions set label='顧客1工場の1回の排水処理量',note='出どころ: ちこさんの試算シート 2026-08-20版の共通前提「バッチ容量 100 m³/バッチ」（メモなし）。同じ表の日処理量 100m³/日のメモは「260812打合せ：m³/日基準」（中島先生との打合せ）。1日1バッチとして、年間バッチ数 ＝ 稼働日/年 × 稼働率。確かめ方: 顧客工場の調整槽の容量と、1日に処理する量を聞いて比べる。 単位は排水m³で、菌体製造kgではない。100m³×300日×稼働率100%＝年30,000m³/工場。' where cost_assumption_id='ca_batch_volume';
update project_cost_models set version_label='261008 好条件・両社採算版',summary_md='好条件の量産設計試算。自然株・色素分解・顧客工場で直接投入・既設槽を使う。自動運転0.5人時/100m³、回収98%・10回使用、光収率1.5g/mol・吸収95%・LED効率3.7µmol/Jで試算。実測性能・設備見積・契約価格ではない。

顧客1工場の排水は年30,000m³。菌体製造量はkg/年で別に計算する。製造設備の原価と、顧客側の装置・工事・運転・清掃等を合算して総額500円/m³の枠を評価する。未見積の設備増額と顧客に残る処理費を残枠から差し引く。

削減の優先順位は、張付きの自動化、培養の光収支、菌体回収と10回の活性維持。定期清掃・冷却・製造運転・脱水・故障対応・管理費は仮定を置いて計上。初期小水量・3年回収の装置販売は別仕様で評価する。',system_scope_md='顧客1工場：100m³/回×300回/年＝排水30,000m³/年。事業全体：顧客工場での排水処理2000万m³/年＋引取処理30,000m³/年。菌体の製造量は各需要に必要補充kg/m³を掛け、販売率で割って導出する。培養・濃縮設備と顧客の排水処理設備を別々に積み上げる。所在地・拠点数・実設備能力は仮定。',target_total_cost_per_m3=null,target_note='顧客の総額提供上限500円/m³を前提行で設定。設備償却・運転・清掃等の両社合算と比較する。既存の500円前後は運転費として読む根拠が強く、償却込みの現状総額は未確認。料金配分は試算で、契約価格・月次売上には未採用。',source_note='原典: Google Sheets SX_コスト試算_260820 (ちこ)。中島先生の設備・運用想定を反映した版。 2026-09-13 に二段階版へ組み替え（migration 393）。 同日、作業リストと販売率を足した（migration 394/395）。 同日、作業の流れの段、オフサイトの比較、金属回収の使用回数の固定を足した（migration 396/397）。 2026-09-14、方式と装置を分け、作業に誰がやるかを持たせた（migration 398/399）。 同日、顧客がやる作業の時間を画面と注記から外した（migration 400）。 同日、色素分解の菌体使用回数を10回にし、明細に誰が持つかを持たせ、顧客工場のリアクター・槽と汚泥の処分を顧客の持ち分にした（migration 402/403）。 同日、年間生産能力を入力から外し、年間処理量（売上10,000,000,000円）から年に作る量を計算する形にした（migration 404/405）。 同日、作業単価を共通の1つにし、前提・作業リスト・明細を「事業と処理の条件 / CAPEX / OPEX」の区分に並べ直した（migration 406/407）。 同日、上端の槽の表示を外し、選んだ組み合わせで使わない前提を薄く出すようにした（migration 409）。 同日、顧客工場の装置の消耗品・電力・点検・交換部品を顧客の持ち分にし、オフサイトの循環カートリッジの処理の運転をSXの作業にした（migration 410）。 同日、文章の中の金額をカンマ区切りの円にそろえた（migration 416）。 同日、オフサイトの売価と年間処理量をオンサイトと別の前提に分けた（migration 419）。 2026-10-08 好条件の採算監査に基づく入力更新（migration487）。旧値と理由を変更記録に保存。' where cost_model_id='cm_p21_260820';
update project_cost_notes set body_md='オンサイトの直接投入は自動化を想定し、0.5人時/100m³を設計仮定として置く。実測ではない。旧7.5人時は先生の手動運転回答として履歴へ保持。顧客負担でも総額の原価に数える。リアクターの所有者スイッチは費用の分担を変え、両社合計を下げない。循環カートリッジの手動5.75人時は据え置き。オフサイトではSOLが運転費を持つ。' where cost_note_id='cn2_c8';
update project_cost_notes set body_md='菌体の年産量＝（顧客工場での事業全体排水量×必要補充kg/m³＋引取処理の事業全体排水量×必要補充kg/m³）÷販売率。顧客1工場の年30,000m³はこの処理量と別。1系列の菌体能力33,333kg/年×排液利用の増殖4倍（設計仮定）＝133,332kg/年で必要系列数を出す。事業規模2000万m³/年を維持するが、総額500から顧客費用を引くため、SOL単独売上100億円を意味しない。系列は比例配賦で、端数系列・拠点分散・所在地・供給距離・実能力は未検証。初期小規模には量産値を流用しない。' where cost_note_id='cn_260820_c4';
update project_cost_notes set body_md='廃液の総額提供上限500円/m³と、燃料の許容原価は別の事業・単位・費用範囲。廃液の旧SOL目標300円/m³は今回解除した。燃料・金属の売却収益で色素分解の赤字を埋めない。燃料モデルの入力と月次・資本政策は今回変更しない。' where cost_note_id='cn_260820_c6';
update project_cost_notes set body_md='- **第1段 菌体の製造原価** — 株ごとに、乾燥菌体1kgをつくる原価。年に作る量は年間処理量から計算し、培養設備を系列の数だけ並べる。培養設備の償却・年ごとの固定費・製造拠点の作業・菌体量に比例する費用に分け、販売率で割って見る
- **菌体費** — 第1段の原価 × 排水1m³あたりに使い切る菌体量
- **運ぶ（巡回・輸送）** — オンサイトは顧客工場への菌体の搬入・搬出と移動、オフサイトは排液の輸送。作業リストの工数・経費と、共通の作業単価で動かす
- **運転・保守・管理** — SXがやる、運ぶ以外の作業（オフサイトの処理の運転、モジュールや膜の交換、閉鎖系の管理など）
- **顧客がやる作業** — オンサイトの処理の運転など。SXの原価にも作業時間にも入れない
- **顧客が持つ明細** — オンサイトのリアクター（処理設備）と槽、装置を動かす消耗品・電力・点検・交換部品、処理水の分析と薬剤、汚泥の処分。SXの原価に入れない（明細の「誰が持つか」で変えられる）
- **使用済み菌体の後処理** — SXが持つ後処理。金属回収は酸処理。色素分解の汚泥の処分は、オンサイトでは顧客が持つので入らない（オフサイトだけ）
- **消耗品・電力・放流など** — オンサイトは菌体を運ぶ容器だけ（回収できずに失う菌体の補充は、2026-09-15 から菌体費に入る）。オフサイトは、SX工場の装置の消耗品・電力・点検・交換部品、処理水の分析と薬剤、放流費
- **設備と槽の償却** — SXが持つ処理設備と槽、金属回収の中央回収設備（2026-09-15 から）の初期投資 ÷ 耐用年数。オンサイトのリアクターと槽は顧客が買うので入らない（オフサイトはSX工場の設備と槽）
- **うち閉鎖系の追加** — 強化株のときだけ乗る費用。上の区分に含まれている分を、第1段の分と合わせて出す
- **総コスト** — 売価（オンサイト500円/m³、オフサイト50,000円/m³）に対して成立するか。総コスト目標はオンサイトにだけ当てる
- **オンサイトの年間 / オフサイトの年間** — 選んだ方式の年間処理量と売価での売上・総コスト・利益。顧客1社の年間を、顧客の数だけ足したもの

顧客総額の上限が設定されたオンサイトでは、顧客の全登録費用（リアクター以外の処分・分析等を含む）を合計し、上限から引いてSOL料金上限を計算する。未入力の残存処理・設備増額は確認待ち。料金上限と残枠は契約額・確定利益ではない。' where cost_note_id='cn_260820_r1';
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('ca_amie_customer_total_budget','cm_p21_260820','総額採算','顧客総額の提供上限（設備・運転等込み）',500,null,'円/m³','H','推定','AMD（内部）',true,'customer_total_budget','まさ2026-10-07〜08の設計条件。SOLと顧客の設備償却・運転・清掃等を合わせた総枠。顧客に費用を移して達成扱いにしない。契約価格ではない。','amd_internal',90,null,'dye');
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('ca_amie_customer_residual_cost','cm_p21_260820','総額採算','顧客に残る既存処理費',null,null,'円/m³','H','推定','AMD（内部）',true,'customer_residual_cost','未確認。色素以外のBOD/COD、窒素・リン、中和、油分、既存清掃・分析等から実際に残る費用を入力。空欄は総額へ含めず、残枠から引く必要がある。','amd_internal',91,null,'dye');
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('ca_amie_unpriced_extra_cost','cm_p21_260820','総額採算','未見積設備・接続等の追加年額換算',null,null,'円/m³','H','推定','AMD（内部）',true,'unpriced_extra_cost','未確認。照射面・液量に対応する設備増額、受入・接続・前処理・敷地・冷却機器・金利等。初期額を年数と実処理量で割る。空欄は0円の見積ではない。','amd_internal',92,null,'dye');
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('ca_amie_culture_cooling_cop','cm_p21_260820','培養の補助運転','培養冷却の成績係数',5,null,'倍','H','推定','AMD（内部）',true,'culture_cooling_cop','好条件COP5。LED電力全量を冷却負荷として計上。LED熱による加温節約を二重計上しない。冷却機器の初期額は追加見積。','amd_internal',276,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('ca_amie_flue_gas_co2_percent','cm_p21_260820','培養の補助運転','受け入れる排ガスのCO₂濃度',6.5,null,'%','H','推定','AMD（内部）',true,'flue_gas_co2_percent','台帳の実験ガス6.5%を参考にする設計仮定。無料CO₂でも搬送電力と受入設備は必要。不純物・前処理は工場ごとに確認。','amd_internal',277,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('ca_amie_flue_gas_pressure_pa','cm_p21_260820','培養の補助運転','排ガス搬送の差圧',10000,null,'Pa','H','推定','AMD（内部）',true,'flue_gas_pressure_pa','搬送の好条件仮定10kPa。配管長・圧損・前処理設備で再見積。','amd_internal',278,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('ca_amie_flue_gas_blower_efficiency','cm_p21_260820','培養の補助運転','排ガス送風機の効率',60,null,'%','H','推定','AMD（内部）',true,'flue_gas_blower_efficiency','好条件の設計仮定60%。モル体積は25℃で24.465m³/kmol、CO₂44.01kg/kmolとして単位照合。','amd_internal',279,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('ca_amie_business_overhead_annual','cm_p21_260820','営業・本部管理','営業・本部管理の年間予算',150000000,null,'円/年','H','推定','AMD（内部）',true,'business_overhead_annual','量産時の原価配賦に使う仮予算。オンサイト事業全体の処理量で割る。月次計画の管理費・資本政策は変更しない。','amd_internal',280,null,null);
insert into project_cost_items (cost_item_id,cost_model_id,scenario,cost_type,group_label,mid_label,leaf_label,basis,quantity,quantity_unit,unit_price,unit_price_unit,price_rule,annual_factor,useful_life_years,is_breakdown,confidence,source_kind,owner,note,visibility,sort_order,strain,application,bearer) values ('ci_amie_cooling','cm_p21_260820','中央培養','OPEX','培養補助運転','培養の冷却電力','培養の冷却電力','毎kg菌体比例',1,'式',183.86807860492067,'円/kg-DCW','culture_cooling',1,null,false,'H','推定','AMD（内部）','照明の電力明細÷冷却成績係数×照明の電力単価。LED数量と買値の変更に連動する。培養補助運転として別計上し、既存の培養ロス補充5%の原料群へ重ねない。年産能力・販売率に応じて1kg原価へ配賦。冷却機器購入額は未見積。','amd_internal',826,null,null,'sx');
insert into project_cost_items (cost_item_id,cost_model_id,scenario,cost_type,group_label,mid_label,leaf_label,basis,quantity,quantity_unit,unit_price,unit_price_unit,price_rule,annual_factor,useful_life_years,is_breakdown,confidence,source_kind,owner,note,visibility,sort_order,strain,application,bearer) values ('ci_amie_flue_gas','cm_p21_260820','中央培養','OPEX','培養補助運転','排ガス搬送の追加電力','排ガス搬送の追加電力','毎kg菌体比例',1,'式',1.5821864373287347,'円/kg-DCW','flue_gas_transport',1,null,false,'H','推定','AMD（内部）','CO₂量÷44.01×24.465÷排ガスCO₂濃度×差圧÷効率÷3600000×電力単価。6.5%、10kPa、60%では菌体1kgあたり約1.582円。排ガスONだけ。既存の散気2kWh/kgは残す。接続・受入・不純物除去の初期額は未見積。','amd_internal',827,null,null,'sx');
insert into project_cost_items (cost_item_id,cost_model_id,scenario,cost_type,group_label,mid_label,leaf_label,basis,quantity,quantity_unit,unit_price,unit_price_unit,price_rule,annual_factor,useful_life_years,is_breakdown,confidence,source_kind,owner,note,visibility,sort_order,strain,application,bearer) values ('ci_amie_overhead','cm_p21_260820','現場共通','OPEX','営業・本部管理','営業・本部管理の配賦','営業・本部管理の配賦','毎m³比例',1,'式',150000000,'円/m³','business_overhead',1,null,false,'H','推定','AMD（内部）','量産時の仮予算1.5億円/年÷オンサイト事業全体の排水量2000万m³＝7.5円/m³。単価欄が年額予算。実体制から見積もるため確定費ではない。月次計画の管理費と合算せず、今回そこを変更しない。金属・燃料の収益で補填しない。','amd_internal',910,null,null,'sx');
insert into project_cost_tasks (cost_task_id,cost_model_id,scenario,group_label,label,hours_per_occurrence,count_driver,count_per_year,hourly_rate,expense_per_occurrence,confidence,source_kind,owner,note,visibility,sort_order,strain,application,performer) values ('ct_amie_tank_cleaning','cm_p21_260820','共通','定期清掃・臨時対応','定期槽清掃（人数×時間の人時）',16,'fixed',4,null,0,'H','推定','AMD（内部）','好条件の設計仮定。2人×8h＝16人時/回、年4回、共通単価4000円/h。年3万m³で8.533円/m³。通常CIP・膜ハウジング清掃等の登録行を残し、槽内の追加清掃のみ。重複が確認できれば減額。周期・外注・機材・排出物は未確認。','amd_internal',43,null,null,'reactor');
insert into project_cost_tasks (cost_task_id,cost_model_id,scenario,group_label,label,hours_per_occurrence,count_driver,count_per_year,hourly_rate,expense_per_occurrence,confidence,source_kind,owner,note,visibility,sort_order,strain,application,performer) values ('ct_amie_fault_response','cm_p21_260820','共通','定期清掃・臨時対応','臨時故障対応（追加作業）',8,'fixed',2,null,0,'H','推定','AMD（内部）','好条件の仮定8人時×年2回。既存の点検・交換部品・予備費は残す。作業が既存費に含まれるか確認し、二重計上なら減額。','amd_internal',44,null,null,'sx');
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,visibility,sort_order,source_url,source_label) values ('cn_amie_hearing_scope','cm_p21_260820','benchmark','顧客の500円前後の費用範囲','かるちゃん7/7共有はランニングコスト500円台後半。設備投資と清掃費は別項目。500〜700円の範囲そのものと清掃の算入は未確認。7/9共有には槽清掃の人手と兼任人件費の過小計上の指摘。個社の年間量・薬品・電力・人時・清掃・修繕・更新費を同じ範囲で比較し、実際に減る費目と残る費目を分ける。','amd_internal',1,'https://teamarmadahq.slack.com/archives/C093DQ4D04W/p1783411970112839','2026-10-07〜08 採算監査');
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,visibility,sort_order,source_url,source_label) values ('cn_amie_optimistic','cm_p21_260820','caveat','好条件の確度と成立条件','約428円/m³は量産・高稼働・自動化・光利用・回収98%を同時に達成する設計仮定。設備増額と既存残存費は未確認で、約72円の残枠から引く。50円の利益を残す場合は追加費合計約22円以内。1系列133,332kg/年に照射面約4512m²・培養液約90m³・LED約976kWが要り、既存の本体873万円がこの能力を持つ見積ではない。','amd_internal',1,null,'2026-10-07〜08 採算監査');
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,visibility,sort_order,source_url,source_label) values ('cn_amie_savings','cm_p21_260820','reading_guide','改善の優先順位と削減効果','元の登録原価の両社合計894円から、手動7.5→0.5人時で280円削減、光収支で約158円削減、その後の回収90→98%で約72円削減。追加工数・冷却・清掃・管理等を積むと約428円。独立の回収改善約118円を約158円と合算しない。排ガス無料と増殖4倍は主因ではない。膜寿命は3年を維持。','amd_internal',1,null,'2026-10-07〜08 採算監査');
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,visibility,sort_order,source_url,source_label) values ('cn_amie_history_261008','cm_p21_260820','history','好条件・両社採算への更新（2026-10-08）','487: まさ2026-10-07承認の好条件設計試算。自動化・光収支・回収率を仮説として採用し清掃等を計上。顧客総額500の枠とSOL料金を区別。実測・契約価格・月次計画の確定ではない。

旧LED108.9kWh・15.1W・315円/W・7年→52.684kWh・7.317W・388.5円/W・5年。回収90→98%。手動工数7.5→0.5h。培養/脱水の空欄→4/.1h。新たに槽清掃・故障対応・冷却・排ガス搬送・管理配賦を追加。旧SOL原価402.5と顧客463.3は旧保存条件の値として履歴に保持。総額上限500から顧客の全登録費用を引く料金上限を導出。旧SOL目標300の設定は解除し、総額500の枠へ集約。燃料・月次・資本政策・長期計画/DDの制作元は変更しない。','amd_internal',230,null,'2026-10-07〜08 採算監査');
commit;
